from decimal import Decimal
from django.contrib.auth import get_user_model
from django.test import TestCase
from django.utils import timezone
from rest_framework.test import APIClient
from audit_log.models import AuditLog
from general_ledger.models import Account,AccountClass,ChartOfAccounts
from master_data.models import Bank,CompanyBankAccount,Currency
from organization.models import Branch,Company
from .models import AccountProfile
class BankApiTests(TestCase):
 def setUp(self):
  self.today=timezone.localdate();self.currency=Currency.objects.get(code="VND");self.company=Company.objects.create(code="BANKCO",name="Bank Co",legal_name="Bank Co Ltd",tax_code="0100444433",accounting_currency=self.currency,legal_reporting_currency=self.currency);self.branch=Branch.objects.create(company=self.company,code="HN",name="Hà Nội");cl=AccountClass.objects.create(company=self.company,code="ASSET",name="Tài sản",normal_balance="DEBIT");chart=ChartOfAccounts.objects.create(company=self.company,code="TT99",name="Hệ thống",effective_from=self.today,is_default=True);self.gl=Account.objects.create(company=self.company,chart_of_accounts=chart,account_class=cl,code="1121",name="Tiền gửi",account_type="ASSET",normal_balance="DEBIT");self.bank=Bank.objects.create(code="TCBTEST",name="Ngân hàng test");self.ba=CompanyBankAccount.objects.create(company=self.company,branch=self.branch,bank=self.bank,account_number="19000001",account_name="BANK CO",currency=self.currency,gl_account=self.gl);self.ba2=CompanyBankAccount.objects.create(company=self.company,branch=self.branch,bank=self.bank,account_number="19000002",account_name="BANK CO 2",currency=self.currency,gl_account=self.gl);self.maker=get_user_model().objects.create_superuser(username="bank-maker",email="maker@bank.test",password="x");self.approver=get_user_model().objects.create_superuser(username="bank-approver",email="approver@bank.test",password="x");self.client=APIClient();self.client.force_authenticate(self.maker);self.q=f"?company_id={self.company.id}";p=self.client.post(f"/api/v1/bank/accounts/{self.q}",{"account":str(self.ba.id),"company":str(self.company.id),"integration_enabled":True,"connector_code":"MOCK"},format="json");self.assertEqual(p.status_code,201,p.data);self.profile=p.data["id"]
 def create_posted_receipt(self):
  x=self.client.post(f"/api/v1/bank/transactions/{self.q}",{"company":str(self.company.id),"account":self.profile,"number":"BC-001","transaction_type":"RECEIPT","business_type":"CUSTOMER_RECEIPT","transaction_date":str(self.today),"counterparty_name":"Khách hàng","currency":str(self.currency.id),"amount":"1000000","exchange_rate":"1","description":"Thu tiền"},format="json");self.assertEqual(x.status_code,201,x.data);tid=x.data["id"];self.client.post(f"/api/v1/bank/transactions/{tid}/submit/{self.q}",{},format="json");self.client.force_authenticate(self.approver);a=self.client.post(f"/api/v1/bank/transactions/{tid}/approve/{self.q}",{"comment":"Duyệt"},format="json");self.assertEqual(a.data["status"],"APPROVED");self.client.force_authenticate(self.maker);p=self.client.post(f"/api/v1/bank/transactions/{tid}/post/{self.q}",{"bank_reference":"REF001"},format="json");self.assertEqual(p.status_code,200,p.data);return tid
 def test_transaction_statement_reconciliation_and_gl(self):
  tid=self.create_posted_receipt();self.assertEqual(AccountProfile.objects.get(pk=self.profile).balance,Decimal("1000000"));statement=self.client.post(f"/api/v1/bank/statements/{self.q}",{"company":str(self.company.id),"account":self.profile,"source":"FILE","source_reference":"STMT-001","period_from":str(self.today),"period_to":str(self.today),"lines":[{"external_id":"LINE-001","transaction_date":str(self.today),"direction":"CREDIT","amount":"1000000","currency":str(self.currency.id),"reference":"REF001","description":"Thu tiền"}]},format="json");self.assertEqual(statement.status_code,201,statement.data);line=statement.data["lines"][0]["id"];matched=self.client.post(f"/api/v1/bank/reconciliations/match/{self.q}",{"statement_line":line,"transaction":tid,"matched_amount":"1000000"},format="json");self.assertEqual(matched.status_code,200,matched.data);self.assertEqual(matched.data["status"],"MATCHED");gl=self.client.post(f"/api/v1/bank/transactions/{tid}/post-gl/{self.q}",{"gl_reference":"GL-BANK-001"},format="json");self.assertEqual(gl.data["gl_status"],"POSTED");self.assertTrue(AuditLog.objects.filter(company=self.company,module_code="BANK").exists())
 def test_transfer_and_idempotent_integration_request(self):
  self.create_posted_receipt();p2=self.client.post(f"/api/v1/bank/accounts/{self.q}",{"account":str(self.ba2.id),"company":str(self.company.id)},format="json");self.assertEqual(p2.status_code,201,p2.data);t=self.client.post(f"/api/v1/bank/transfers/{self.q}",{"company":str(self.company.id),"number":"DC-001","source_account":self.profile,"destination_account":p2.data["id"],"transfer_date":str(self.today),"source_amount":"300000","destination_amount":"300000","exchange_rate":"1","description":"Điều chuyển"},format="json");self.assertEqual(t.status_code,201,t.data);c=self.client.post(f"/api/v1/bank/transfers/{t.data['id']}/confirm/{self.q}",{},format="json");self.assertEqual(c.data["status"],"CONFIRMED");self.assertEqual(AccountProfile.objects.get(pk=p2.data["id"]).balance,Decimal("300000"));tx=self.client.post(f"/api/v1/bank/transactions/{self.q}",{"company":str(self.company.id),"account":self.profile,"number":"PC-API","transaction_type":"PAYMENT","business_type":"VENDOR_PAYMENT","transaction_date":str(self.today),"counterparty_name":"Nhà cung cấp","currency":str(self.currency.id),"amount":"100000","exchange_rate":"1","description":"Chi API"},format="json");sent=self.client.post(f"/api/v1/bank/transactions/{tx.data['id']}/send-bank/{self.q}",{"idempotency_key":"IDEMP-001","payload":{"amount":100000}},format="json");self.assertEqual(sent.status_code,200,sent.data);duplicate=self.client.post(f"/api/v1/bank/transactions/{tx.data['id']}/send-bank/{self.q}",{"idempotency_key":"IDEMP-001"},format="json");self.assertEqual(duplicate.status_code,400)
